-- Requirements 5. Test fixture for MariaDB. Run against the intended test schema.
-- Accounts use the project's BCrypt hash for the requested test-only password.
-- A second run or a conflicting login/email raises an error and rolls back.
-- This batch uses only the 76 regions listed in docs/요구사항5_미사용_지역.md
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @req5_old_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = CONCAT_WS(',', NULLIF(@@SESSION.sql_mode, ''), 'NO_BACKSLASH_ESCAPES');

CREATE TEMPORARY TABLE req5_course (
    seed_no INT PRIMARY KEY, account_no INT NOT NULL, region_id BIGINT NOT NULL,
    region_code VARCHAR(30) NOT NULL, destination VARCHAR(100) NOT NULL,
    start_date DATE NOT NULL, end_date DATE NOT NULL, companion_type VARCHAR(30) NOT NULL,
    adults INT NOT NULL, children INT NOT NULL, transport_type VARCHAR(30) NOT NULL,
    title VARCHAR(200) NOT NULL, summary TEXT NOT NULL,
    preferences JSON NOT NULL, metadata JSON NOT NULL, route_hash CHAR(64) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE req5_day (
    seed_no INT NOT NULL, day_no INT NOT NULL, theme VARCHAR(200) NOT NULL,
    visit_date DATE NOT NULL, PRIMARY KEY (seed_no, day_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE req5_place (
    place_id BIGINT PRIMARY KEY, region_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL,
    place_type VARCHAR(30) NOT NULL, address VARCHAR(300) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE req5_account (
    account_no INT PRIMARY KEY, login_id VARCHAR(50) NOT NULL, email VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





DELIMITER //
BEGIN NOT ATOMIC
    DECLARE method_id INT;
    DECLARE held_lock INT DEFAULT 0;
    DECLARE inserted_courses INT;
    DECLARE inserted_days INT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        IF held_lock = 1 THEN
            DO RELEASE_LOCK('smart_traveler.req5_seed');
        END IF;
        SET SESSION sql_mode = @req5_old_sql_mode;
        RESIGNAL;
    END;

    SET held_lock = GET_LOCK('smart_traveler.req5_seed', 10);
    IF COALESCE(held_lock, 0) <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Could not lock the requirements 5 import.';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM req5_account) <> 100
       OR (SELECT COUNT(*) FROM req5_course) <> 2000
       OR EXISTS (
           SELECT 1 FROM req5_account a LEFT JOIN req5_course s ON s.account_no = a.account_no
           GROUP BY a.account_no HAVING COUNT(s.seed_no) <> 20
       ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expected 100 accounts with 20 distinct courses each.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM members m JOIN req5_account a ON m.login_id = a.login_id OR m.email = a.email
    ) OR EXISTS (
        SELECT 1 FROM course c WHERE JSON_VALUE(c.condition_meta, '$.seed_batch') = 'smart-traveler-rag-2000-v1'
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A test account or this course batch already exists.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM req5_course s
        LEFT JOIN region r ON r.region_id = s.region_id AND BINARY r.region_code = BINARY s.region_code
            AND BINARY r.full_name = BINARY s.destination AND r.is_supported = 1 AND r.abolished_at IS NULL
        WHERE r.region_id IS NULL
    ) OR EXISTS (
        SELECT 1 FROM req5_place s
        LEFT JOIN place p ON p.place_id = s.place_id AND p.region_id = s.region_id AND p.is_active = 1
            AND BINARY p.name = BINARY s.name AND BINARY p.place_type = BINARY s.place_type
            AND BINARY COALESCE(p.address, '') = BINARY s.address
        WHERE p.place_id IS NULL
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A referenced region or active place is missing or changed.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM course c
        JOIN (SELECT DISTINCT region_id, region_code, destination FROM req5_course) s
            ON c.region_id = s.region_id
            OR NULLIF(c.region_code, '') = s.region_code OR TRIM(c.destination) = s.destination
            OR (c.region_id IS NULL AND NULLIF(c.region_code, '') IS NULL AND EXISTS (
                SELECT 1 FROM region r WHERE r.region_id = s.region_id
                    AND r.region_name = CONCAT(TRIM(c.destination), '시')
            ))
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A selected region is now in use by another course.';
    END IF;

    SELECT MAX(id) INTO method_id FROM generation_method WHERE code = 'ai';
    IF method_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The ai generation method is missing.';
    END IF;

    SELECT login_id, login_id, email, '$2a$10$34P7j5RsomxUAe3CWO2DZe2l1jAatHOFPPBw0uHAlsTi2QxfGNAbu', 'USER', 'ACTIVE'
    FROM req5_account ORDER BY account_no;
    IF ROW_COUNT() <> 100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expected to insert 100 test accounts.';
    END IF;

        member_no, region_id, region_code, destination, start_date, end_date,
        companion_type, adults, children, transport_type, title, summary,
        preferences_snapshot, condition_meta, generation_method_id, flow_type, status, share_consent
    )
    SELECT m.member_id, s.region_id, s.region_code, s.destination, s.start_date, s.end_date,
           s.companion_type, s.adults, s.children, s.transport_type, s.title, s.summary,
           s.preferences, s.metadata, method_id, 'COURSE_FIRST', 'done', b'0'
    FROM req5_course s JOIN req5_account a ON a.account_no = s.account_no
    JOIN members m ON m.login_id = a.login_id AND m.email = a.email
    ORDER BY s.seed_no;
    SET inserted_courses = ROW_COUNT();
    IF inserted_courses <> 2000 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expected to insert 2,000 courses.';
    END IF;

    SELECT c.id, d.day_no, d.theme, d.visit_date FROM course c
    JOIN req5_day d ON d.seed_no = CAST(JSON_VALUE(c.condition_meta, '$.seed_no') AS UNSIGNED)
    WHERE JSON_VALUE(c.condition_meta, '$.seed_batch') = 'smart-traveler-rag-2000-v1';
    SET inserted_days = ROW_COUNT();
    IF inserted_days <> (SELECT COUNT(*) FROM req5_day)
       OR inserted_days <> (SELECT SUM(DATEDIFF(end_date, start_date) + 1) FROM req5_course) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inserted day count does not match the course durations.';
    END IF;
    COMMIT;
    DO RELEASE_LOCK('smart_traveler.req5_seed');
    SELECT 100 AS accounts_inserted, inserted_courses AS courses_inserted, inserted_days AS course_days_inserted;
END//
DELIMITER ;

DROP TEMPORARY TABLE req5_account, req5_course, req5_day, req5_place;
SET SESSION sql_mode = @req5_old_sql_mode;
